function parseToken(authHeader) {
  // Return only the token substring
  if (!authHeader) return null;
  return authHeader.split(' ')[1];
}

console.log(parseToken('Bearer eyJhbGciOiJIUzI1NiIsIn...'));

function filterTopUsers(users) {
  return users.filter(u => u.isActive && u.xp >= 100);
}

const sample = [{ name: 'A', isActive: true, xp: 120 }, { name: 'B', isActive: false, xp: 200 }];
console.log(filterTopUsers(sample));

function buildBadge(label, color = 'blue') {
  return `<span class="badge bg-${color}">${label}</span>`;
}

console.log(buildBadge('Web Dev', 'purple'));

function transposeMatrix(matrix) {
  return matrix[0].map((_, colIndex) => matrix.map(row => row[colIndex]));
}

console.log(transposeMatrix([[1, 2], [3, 4]]));

function calcAccuracy(correct, total) {
  return ((correct / total) * 100).toFixed(2) + '%';
}

console.log(calcAccuracy(85, 100));

function twoSumSorted(arr, target) {
  let left = 0, right = arr.length - 1;
  while (left < right) {
    let sum = arr[left] + arr[right];
    if (sum === target) return [left, right];
    if (sum < target) left++;
    else right--;
  }
  return null;
}

console.log(twoSumSorted([2, 7, 11, 15], 9));

function inorder(root, res = []) {
  if (!root) return res;
  inorder(root.left, res);
  res.push(root.val);
  inorder(root.right, res);
  return res;
}

const tree = { val: 2, left: { val: 1, left: null, right: null }, right: { val: 3, left: null, right: null } };
console.log(inorder(tree));

function fibMemo(n, memo = {}) {
  if (n <= 1) return n;
  if (memo[n]) return memo[n];
  memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  return memo[n];
}

console.log(fibMemo(10)); // 55

function buildSelectQuery(table, cols = ['*']) {
  return `SELECT ${cols.join(', ')} FROM ${table};`;
}

console.log(buildSelectQuery('students', ['id', 'name', 'gpa']));

function hasUniqueKeys(records, keyName = 'id') {
  const seen = new Set();
  for (const r of records) {
    if (seen.has(r[keyName])) return false;
    seen.add(r[keyName]);
  }
  return true;
}

console.log(hasUniqueKeys([{ id: 1 }, { id: 2 }, { id: 1 }]));

function percentChange(oldVal, newVal) {
  const diff = newVal - oldVal;
  return ((diff / oldVal) * 100).toFixed(1) + '%';
}

console.log(percentChange(50, 75)); // +50.0%

function jointWorkDays(daysA, daysB) {
  return ((daysA * daysB) / (daysA + daysB)).toFixed(2);
}

console.log(jointWorkDays(10, 15)); // 6.00 days

